void fillRect(const Rect& r, const void* pix) {
    if (r.isEmpty())
        return;

    int width = r.right - r.left;
    int height = r.bottom - r.top;
    int bytesPerPixel = r.format.bytesPerPixel;

    if (bytesPerPixel == 1) {
        // Single byte per pixel; fill with a byte value
        unsigned char pixelValue = *static_cast<const unsigned char*>(pix);
        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                r.buffer[(r.top + y) * r.stride + (r.left + x)] = pixelValue;
            }
        }
    } else {
        // Multiple bytes per pixel; copy pixel data
        const unsigned char* pixelData = static_cast<const unsigned char*>(pix);
        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                unsigned char* dst = &r.buffer[(r.top + y) * r.stride + (r.left + x) * bytesPerPixel];
                for (int i = 0; i < bytesPerPixel; ++i) {
                    dst[i] = pixelData[i];
                }
            }
        }
    }
}

