void fillRect(const Rect& r, const void* pix) {
    if (r.isEmpty()) {
        return;
    }

    int width = r.width();
    int height = r.height();
    int bytesPerPixel = r.bytesPerPixel();

    if (bytesPerPixel == 1) {
        // Single byte per pixel, set memory directly
        unsigned char value = *(static_cast<const unsigned char*>(pix));
        for (int y = 0; y < height; ++y) {
            unsigned char* row = r.buffer + (r.y + y) * r.stride;
            for (int x = 0; x < width; ++x) {
                row[r.x + x] = value;
            }
        }
    } else {
        // Multiple bytes per pixel, copy pixel data
        for (int y = 0; y < height; ++y) {
            unsigned char* row = r.buffer + (r.y + y) * r.stride;
            for (int x = 0; x < width; ++x) {
                unsigned char* dest = row + r.x * bytesPerPixel;
                const unsigned char* src = static_cast<const unsigned char*>(pix);
                for (int i = 0; i < bytesPerPixel; ++i) {
                    dest[i] = src[i];
                }
            }
        }
    }

    r.commit();
}

void fillPixelBuffer(const Rect& r, const void* pix) {
    if (r.isEmpty()) {
        return;
    }

    int width = r.width();
    int height = r.height();
    int bytesPerPixel = r.bytesPerPixel();
    uchar* pixels = r.pixels();

    if (bytesPerPixel == 1) {
        // Single byte pixel data
        uchar value = *static_cast<const uchar*>(pix);
        for (int y = 0; y < height; ++y) {
            std::fill(pixels + y * r.stride(), pixels + y * r.stride() + width, value);
        }
    } else {
        // Multiple byte pixel data
        int size = width * bytesPerPixel;
        for (int y = 0; y < height; ++y) {
            std::memcpy(pixels + y * r.stride(), pix, size);
        }
    }

    r.commit();
}
